mapper.select:
select
a.mete_id,
a.mete_type,
a.mete_kind,
a.mete_name,
a.mete_code,
a.unit,
a.mete_explain_type,
a.create_time,
a.update_time,
a.modulus,
a.station_name,
a.station_id,
a.up_effect,
a.down_effect,
a.alarmlevel,
a.alarmthresbhold,
a.describer,
a.mete_precision,
a.change_limit,
a.hilimit1,
a.lolimit1,
a.hilimit2,
a.lolimit2,
a.hilimit3,
a.lolimit3,
a.hilimit4,
a.stander,
a.controlenable
from t_cfg_mete a
where 1 = 1
 and a.mete_id = #{meteId, jdbcType=VARCHAR}
 and a.mete_type = #{meteType, jdbcType=VARCHAR}
 and a.mete_kind = #{meteKind, jdbcType=INTEGER}
 and a.mete_name = #{meteName, jdbcType=VARCHAR}
 and a.mete_code = #{meteCode, jdbcType=VARCHAR}
 and a.unit = #{unit, jdbcType=VARCHAR}
 and a.mete_explain_type = #{meteExplainType, jdbcType=VARCHAR}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}
 and a.modulus = #{modulus, jdbcType=INTEGER}
 and a.station_name = #{stationName, jdbcType=VARCHAR}
 and a.station_id = #{stationId, jdbcType=VARCHAR}
 and a.up_effect = #{upEffect, jdbcType=INTEGER}
 and a.down_effect = #{downEffect, jdbcType=INTEGER}
 and a.alarmlevel = #{alarmlevel, jdbcType=INTEGER}
 and a.alarmthresbhold = #{alarmthresbhold, jdbcType=INTEGER}
 and a.describer = #{describer, jdbcType=VARCHAR}
 and a.mete_precision = #{metePrecision, jdbcType=INTEGER}
 and a.change_limit = #{changeLimit, jdbcType=REAL}
 and a.hilimit1 = #{hilimit1, jdbcType=REAL}
 and a.lolimit1 = #{lolimit1, jdbcType=REAL}
 and a.hilimit2 = #{hilimit2, jdbcType=REAL}
 and a.lolimit2 = #{lolimit2, jdbcType=REAL}
 and a.hilimit3 = #{hilimit3, jdbcType=REAL}
 and a.lolimit3 = #{lolimit3, jdbcType=REAL}
 and a.hilimit4 = #{hilimit4, jdbcType=REAL}
 and a.stander = #{stander, jdbcType=REAL}
 and a.controlenable = #{controlenable, jdbcType=INTEGER}

